A minimal but real RAG pipeline in Python with PostgreSQL + pgvector.

```sql
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE chunks (id BIGSERIAL PRIMARY KEY, doc TEXT, body TEXT, embedding vector(384));
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops);
```

```python
from sentence_transformers import SentenceTransformer
import psycopg

embedder = SentenceTransformer('all-MiniLM-L6-v2')

def ingest(conn, doc, text, size=800, overlap=100):
    for i in range(0, len(text), size - overlap):
        body = text[i:i + size]
        conn.execute('INSERT INTO chunks (doc, body, embedding) VALUES (%s, %s, %s)',
                     (doc, body, str(embedder.encode(body).tolist())))

def retrieve(conn, question, k=4):
    q = str(embedder.encode(question).tolist())
    return conn.execute('SELECT body FROM chunks ORDER BY embedding <=> %s LIMIT %s', (q, k)).fetchall()
```

